"""Black-box tests for todo.py, derived only from SPEC.md.

Each test invokes todo.py as a subprocess with an isolated cwd (pytest's
tmp_path fixture), so each test gets its own todo.json.
"""

import json
import subprocess
import sys

import pytest


def run_todo(cwd, *args):
    """Run `python3 todo.py <args>` with cwd as the working directory."""
    return subprocess.run(
        [sys.executable, str(cwd_todo_py())] + list(args),
        cwd=cwd,
        capture_output=True,
        text=True,
    )


def cwd_todo_py():
    # todo.py is expected to live at the repository root, alongside this
    # test file. We resolve it relative to this file's directory so that
    # tests work regardless of the invocation's cwd.
    import pathlib

    return pathlib.Path(__file__).resolve().parent / "todo.py"


def todo_json_path(tmp_path):
    return tmp_path / "todo.json"


def write_todo_json(tmp_path, data):
    todo_json_path(tmp_path).write_text(json.dumps(data))


def read_todo_json(tmp_path):
    return json.loads(todo_json_path(tmp_path).read_text())


# ---------------------------------------------------------------------------
# add
# ---------------------------------------------------------------------------


def test_add_to_empty_list_creates_file_and_prints_confirmation(tmp_path):
    assert not todo_json_path(tmp_path).exists()

    result = run_todo(tmp_path, "add", "Buy", "milk")

    assert result.returncode == 0
    assert result.stdout == "Added task 1: Buy milk\n"
    assert todo_json_path(tmp_path).exists()
    assert read_todo_json(tmp_path) == {
        "tasks": [{"id": 1, "text": "Buy milk", "done": False}]
    }


def test_add_single_argument_text(tmp_path):
    result = run_todo(tmp_path, "add", "Buy milk")

    assert result.returncode == 0
    assert result.stdout == "Added task 1: Buy milk\n"
    assert read_todo_json(tmp_path) == {
        "tasks": [{"id": 1, "text": "Buy milk", "done": False}]
    }


def test_add_to_non_empty_list_assigns_next_id(tmp_path):
    write_todo_json(
        tmp_path,
        {"tasks": [{"id": 1, "text": "Buy milk", "done": False}]},
    )

    result = run_todo(tmp_path, "add", "Write", "report")

    assert result.returncode == 0
    assert result.stdout == "Added task 2: Write report\n"
    data = read_todo_json(tmp_path)
    assert data == {
        "tasks": [
            {"id": 1, "text": "Buy milk", "done": False},
            {"id": 2, "text": "Write report", "done": False},
        ]
    }


def test_add_assigns_max_existing_id_plus_one(tmp_path):
    write_todo_json(
        tmp_path,
        {
            "tasks": [
                {"id": 1, "text": "Buy milk", "done": False},
                {"id": 5, "text": "Old task", "done": True},
            ]
        },
    )

    result = run_todo(tmp_path, "add", "New task")

    assert result.returncode == 0
    assert result.stdout == "Added task 6: New task\n"


def test_add_with_no_text_is_an_error(tmp_path):
    result = run_todo(tmp_path, "add")

    assert result.returncode == 1
    assert "Error: add requires <text>" in result.stderr
    assert result.stdout == ""
    assert not todo_json_path(tmp_path).exists()


def test_add_with_no_text_does_not_modify_existing_file(tmp_path):
    original = {"tasks": [{"id": 1, "text": "Buy milk", "done": False}]}
    write_todo_json(tmp_path, original)

    result = run_todo(tmp_path, "add")

    assert result.returncode == 1
    assert "Error: add requires <text>" in result.stderr
    assert result.stdout == ""
    assert read_todo_json(tmp_path) == original


# ---------------------------------------------------------------------------
# list
# ---------------------------------------------------------------------------


def test_list_with_existing_tasks(tmp_path):
    write_todo_json(
        tmp_path,
        {
            "tasks": [
                {"id": 1, "text": "Buy milk", "done": True},
                {"id": 2, "text": "Write report", "done": False},
            ]
        },
    )

    result = run_todo(tmp_path, "list")

    assert result.returncode == 0
    assert result.stdout == "[1] [x] Buy milk\n[2] [ ] Write report\n"


def test_list_orders_by_ascending_id(tmp_path):
    write_todo_json(
        tmp_path,
        {
            "tasks": [
                {"id": 2, "text": "Second added, but shown after", "done": False},
                {"id": 1, "text": "First id", "done": False},
            ]
        },
    )

    result = run_todo(tmp_path, "list")

    assert result.returncode == 0
    lines = result.stdout.splitlines()
    assert lines == [
        "[1] [ ] First id",
        "[2] [ ] Second added, but shown after",
    ]


def test_list_with_missing_file_prints_no_tasks_and_does_not_create_file(tmp_path):
    assert not todo_json_path(tmp_path).exists()

    result = run_todo(tmp_path, "list")

    assert result.returncode == 0
    assert result.stdout == "No tasks.\n"
    assert not todo_json_path(tmp_path).exists()


def test_list_with_empty_tasks_array_prints_no_tasks(tmp_path):
    write_todo_json(tmp_path, {"tasks": []})

