#!/usr/bin/env python3
"""todo: a small command-line to-do list manager.

Usage:
    python3 todo.py add <text>
    python3 todo.py list
    python3 todo.py done <id>

Tasks are persisted as JSON to ./todo.json (relative to the current
working directory of the process).
"""

import json
import os
import sys

TODO_FILE = "todo.json"


def load_tasks():
    """Return the list of tasks from TODO_FILE, or [] if it doesn't exist."""
    if not os.path.exists(TODO_FILE):
        return []
    with open(TODO_FILE, "r") as f:
        data = json.load(f)
    return data.get("tasks", [])


def save_tasks(tasks):
    with open(TODO_FILE, "w") as f:
        json.dump({"tasks": tasks}, f)


def cmd_add(args):
    if not args:
        print("Error: add requires <text>", file=sys.stderr)
        return 1

    text = " ".join(args).strip()
    tasks = load_tasks()
    next_id = max((t["id"] for t in tasks), default=0) + 1
    tasks.append({"id": next_id, "text": text, "done": False})
    save_tasks(tasks)
    print(f"Added task {next_id}: {text}")
    return 0


def cmd_list(args):
    tasks = load_tasks()
    if not tasks:
        print("No tasks.")
        return 0

    for task in sorted(tasks, key=lambda t: t["id"]):
        mark = "x" if task["done"] else " "
        print(f"[{task['id']}] [{mark}] {task['text']}")
    return 0


def cmd_done(args):
    if not args:
        print("Error: done requires <id>", file=sys.stderr)
        return 1

    id_str = args[0]
    try:
        task_id = int(id_str)
    except ValueError:
        print(f"Error: invalid id '{id_str}'", file=sys.stderr)
        return 1

    tasks = load_tasks()
    for task in tasks:
        if task["id"] == task_id:
            task["done"] = True
            save_tasks(tasks)
            print(f"Done: {task_id}")
            return 0

    print(f"Error: no task with id {task_id}", file=sys.stderr)
    return 1


def main(argv):
    if not argv:
        print("Error: no command given", file=sys.stderr)
        return 1

    command, rest = argv[0], argv[1:]

    if command == "add":
        return cmd_add(rest)
    elif command == "list":
        return cmd_list(rest)
    elif command == "done":
        return cmd_done(rest)
    else:
        print(f"Error: unknown command '{command}'", file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

